import { Command } from '@refy-design/web';
import type { CommandItem } from '@refy-design/web';
import { HelpMenu } from '@refy-design/web';
import { NotificationBell } from '@refy-design/web';
import type { NotificationItem } from '@refy-design/web';
import { Topbar } from '@refy-design/web';
import { UserMenu } from '@refy-design/web';
import { createContext } from 'react';
import type { RefObject } from 'react';
import { useContext } from 'react';
import { useEffect } from 'react';
import { useState } from 'react';
const notifications: NotificationItem[] = [
  {
    id: 'n1',
    title: 'Review complete',
    description: 'refy.com.br: 84 pages, 12 critical.',
    time: '5 min ago',
    unread: true,
  },
  {
    id: 'n2',
    title: 'Project moved ahead 4 steps',
    description: 'Aurora project in the current cycle.',
    time: '2h ago',
    unread: true,
  },
  {
    id: 'n3',
    title: 'Invite accepted',
    description: 'Ana Costa joined the workspace.',
    time: '3d ago',
  },
];
const ExampleScope = createContext<RefObject<HTMLDivElement | null> | null>(null);
function useCommandShortcut(onOpen: () => void, enabled = true) {
  const scope = useContext(ExampleScope);
  useEffect(() => {
    if (!enabled) return;
    const onKey = (event: KeyboardEvent) => {
      if (
        event.defaultPrevented ||
        (scope && !scope.current?.contains(event.target as Node))
      )
        return;
      if (event.key.toLowerCase() === 'k' && (event.metaKey || event.ctrlKey)) {
        event.preventDefault();
        onOpen();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [scope, onOpen, enabled]);
}
const commands: CommandItem[] = [
  { id: 'new', label: 'Create new project', group: 'Actions', shortcut: '⌘N' },
  { id: 'rerun', label: 'Re-run last update', group: 'Actions', shortcut: '⌘R' },
  { id: 'rd', label: 'aurora.example.com', group: 'Recent projects', lead: 'RD' },
];
export function Example() {
  const [commandOpen, setCommandOpen] = useState(false);
  const [items, setItems] = useState(notifications);
  useCommandShortcut(() => setCommandOpen(true));
  return (
    <div style={{ minHeight: 480 }}>
      <Topbar
        brand="refy"
        crumbs={[{ label: 'Example team', href: '#' }, { label: 'Overview' }]}
        onSearchClick={() => setCommandOpen(true)}
        actions={
          <>
            <NotificationBell
              items={items}
              onItemClick={(item) =>
                setItems((l) =>
                  l.map((n) => (n.id === item.id ? { ...n, unread: false } : n)),
                )
              }
              onMarkAllRead={() =>
                setItems((l) => l.map((n) => ({ ...n, unread: false })))
              }
            />
            <HelpMenu />
            <UserMenu
              user={{ name: 'João Mendes', email: 'joao@example.com', initials: 'JM' }}
              compact
            />
          </>
        }
      />
      <p
        style={{
          padding: 24,
          fontFamily: 'var(--font-mono)',
          fontSize: 12,
          color: 'var(--ink-3)',
        }}
      >
        Click search or press ⌘K · bell, help and avatar open too.
      </p>
      <Command open={commandOpen} onOpenChange={setCommandOpen} items={commands} />
    </div>
  );
}

import { Topbar } from '@refy-design/web';
import { UserMenu } from '@refy-design/web';
import { useState } from 'react';
const appTabs = [
  { id: 'view', label: 'Overview' },
  { id: 'clients', label: 'Clients', badge: 18 },
  { id: 'contents', label: 'Content' },
  { id: 'activities', label: 'Activity', badge: 4 },
];
export function Example() {
  const [tab, setTab] = useState('view');
  return (
    <div style={{ minHeight: 360 }}>
      <Topbar
        brand="refy"
        composition="tabs"
        crumbs={[{ label: 'Portfolio' }, { label: 'Overview' }]}
        tabs={appTabs}
        tabValue={tab}
        onTabChange={setTab}
        actions={
          <UserMenu
            user={{ name: 'Ana Silva', email: 'ana@example.com', initials: 'AS' }}
            compact
          />
        }
      />
      <p role="status" style={{ padding: 24, color: 'var(--ink-2)' }}>
        Active area: {tab}.
      </p>
    </div>
  );
}

